func FinishIssueStopwatch(ctx context.Context, user *user_model.User, issue *Issue) (ok bool, err error) {
	sw, exists, err := getStopwatch(ctx, user.ID, issue.ID)
	if err != nil {
		return false, err
	} else if !exists {
		return false, nil
	}
	if err = finishIssueStopwatch(ctx, user, issue, sw); err != nil {
		return false, err
	}
	return true, nil
}

